def load() -> pd.DataFrame:
    import numpy as np
    import pandas as pd
    from cdflib import CDF
    from cdflib import epochs

    path = 'data/astronomy/input/swarm/SW_OPER_ACCACAL_2__20240511T000000_20240511T235959_0304.cdf'
    cdf = CDF(path)

    info = cdf.cdf_info()
    zvars = list(getattr(info, 'zVariables', []) or [])

    # Pick time and along-track acceleration variables
    def pick_var(candidates, contains=None):
        for v in candidates:
            if v in zvars:
                return v
        if contains:
            for v in zvars:
                vv = v.lower()
                if any(c in vv for c in contains):
                    return v
        return None

    time_var = pick_var(['time', 'epoch', 'Epoch', 'TT2000', 'tt2000'], contains=['time', 'epoch', 'tt2000'])
    acc_var = pick_var(['a_aa', 'A_AA', 'accAlong', 'acc_along', 'along_acc'], contains=['a_aa', 'acc'])
    if time_var is None:
        raise ValueError(f'Could not find time variable in zVariables={zvars}')
    if acc_var is None:
        raise ValueError(f'Could not find along-track acceleration variable in zVariables={zvars}')

    t_raw = cdf.varget(time_var)
    acc_raw = cdf.varget(acc_var)

    # Flatten to 1D where possible
    t_raw = np.asarray(t_raw)
    acc_raw = np.asarray(acc_raw)

    # time should be 1D already
    if t_raw.ndim != 1:
        t_raw = t_raw.reshape(-1)

    # acceleration may be (N,1) or (N,) — squeeze
    acc = np.squeeze(acc_raw)
    if acc.ndim != 1:
        acc = acc.reshape(-1)

    # Align lengths robustly (truncate to min)
    n = min(len(t_raw), len(acc))
    t_raw = t_raw[:n]
    acc = acc[:n]

    # Convert times
    try:
        t_dt = epochs.CDFepoch.to_datetime(t_raw)
    except Exception:
        try:
            t_dt = epochs.CDFepoch.to_datetime(epochs.CDFepoch.convert_to_cdfepoch(t_raw))
        except Exception:
            t_dt = pd.to_datetime(t_raw, errors='coerce')

    time = pd.to_datetime(t_dt, errors='coerce')

    # Handle fill values for acceleration
    try:
        atts = cdf.varattsget(acc_var)
    except Exception:
        atts = {}

    fill_keys = [k for k in ['FILLVAL', 'FillVal', '_FillValue', 'VALIDMIN', 'VALIDMAX'] if k in atts]
    for k in ['FILLVAL', 'FillVal', '_FillValue']:
        if k in atts:
            fv = atts[k]
            try:
                fv = float(np.array(fv).reshape(-1)[0])
                acc = np.where(acc == fv, np.nan, acc)
            except Exception:
                pass

    # Common sentinels
    for s in [1e30, -1e30, 1e31, -1e31, 9.99e30, -9.99e30, 99999, -99999]:
        acc = np.where(acc == s, np.nan, acc)

    df = pd.DataFrame({'time': time, 'accAlong': pd.to_numeric(acc, errors='coerce')})
    df = df.dropna(subset=['time']).sort_values('time').reset_index(drop=True)
    return df

def load() -> pd.DataFrame:
    import pandas as pd
    import cdflib

    path = 'data/astronomy/input/swarm/SW_OPER_ACCACAL_2__20240511T000000_20240511T235959_0304.cdf'
    cdf = cdflib.CDF(path)
    info = cdf.cdf_info()

    # cdflib returns a CDFInfo object; introspect via __dict__ and dir
    d = {}
    if hasattr(info, '__dict__'):
        for k, v in info.__dict__.items():
            try:
                d[k] = str(v)
            except Exception:
                d[k] = repr(v)

    rows = []
    rows.append({'section': 'cdf_info_dir', 'key': 'dir', 'value': ','.join([x for x in dir(info) if not x.startswith('_')])})
    for k, v in d.items():
        rows.append({'section': 'cdf_info_dict', 'key': k, 'value': v[:2000]})

    # try common attribute names for variable lists
    for attr in ['rVariables', 'zVariables', 'rvariables', 'zvariables']:
        if hasattr(info, attr):
            val = getattr(info, attr)
            rows.append({'section': 'cdf_info_attr', 'key': attr, 'value': str(val)[:4000]})

    # also show cdf varget list, if possible
    try:
        rows.append({'section': 'cdf', 'key': 'cdf_info_raw', 'value': str(info)[:4000]})
    except Exception:
        pass

    return pd.DataFrame(rows)
